/**
 * this function is a POSIX compliant version, which shall check the file named
 * by the pathname pointed to by the path argument for accessibility according
 * to the bit pattern contained in amode.
 *
 * @param path the specified file/dir path.
 * @param amode the value is either the bitwise-inclusive OR of the access
 * permissions to be checked (R_OK, W_OK, X_OK) or the existence test (F_OK).
 */
int access(const char *path, int amode)
{
    struct stat st;

    if (path == NULL)
    {
        rt_set_errno(-EINVAL);
        return -1;
    }

    if (stat(path, &st) < 0)
    {
        rt_set_errno(-ENOENT);
        return -1;
    }

    if (amode == F_OK)
    {
        return 0;
    }

    if ((amode & R_OK) && !(st.st_mode & S_IRUSR))
    {
        rt_set_errno(-EACCES);
        return -1;
    }

    if ((amode & W_OK) && !(st.st_mode & S_IWUSR))
    {
        rt_set_errno(-EACCES);
        return -1;
    }

    if ((amode & X_OK) && !(st.st_mode & S_IXUSR))
    {
        rt_set_errno(-EACCES);
        return -1;
    }

    return 0;
}

