#include <dfs.h>
#include <unistd.h>

#include <dfs_dentry.h>
#include <dfs_mnt.h>
#include "dfs_private.h"

#ifdef RT_USING_SMART
#include <lwp.h>
#endif

/**
 * @addtogroup group_FsPosixApi
 * @{
 */

/**
 * this function is a POSIX compliant version, which will open a file and
 * return a file descriptor according specified flags.
 *
 * @param file the path name of file.
 * @param flags the file open flags. Common values include:
 *     - Access modes (mutually exclusive):
 *         - `O_RDONLY`: Open for read-only access.
 *         - `O_WRONLY`: Open for write-only access.
 *         - `O_RDWR`: Open for both reading and writing.
 *     - File status flags (can be combined with bitwise OR `|`):
 *         - `O_CREAT`: Create the file if it does not exist. Requires a `mode` argument.
 *         - `O_TRUNC`: Truncate the file to zero length if it already exists.
 *         - `O_APPEND`: Append writes to the end of the file.
 *         - `O_EXCL`: Ensure that `O_CREAT` creates the file exclusively.
 *         - Other platform-specific flags
 *
 * @return the non-negative integer on successful open, others for failed.
 */
int open(const char *file, int flags, ...)
{
    int fd, result;
    struct dfs_file *df = RT_NULL;
    mode_t mode = 0;

    if (file == NULL)
    {
        rt_set_errno(-EBADF);
        return -1;
    }

    if ((flags & O_CREAT) || (flags & O_TMPFILE) == O_TMPFILE)
    {
        va_list ap;
        va_start(ap, flags);
        mode = va_arg(ap, mode_t);
        va_end(ap);
    }

    fd = fd_new();
    if (fd >= 0)
    {
        df = fd_get(fd);
    }
    else
    {
        rt_set_errno(-RT_ERROR);
        return RT_NULL;
    }

    result = dfs_file_open(df, file, flags, mode);
    if (result < 0)
    {
        fd_release(fd);
        rt_set_errno(result);
        return -1;
    }

    return fd;
}
RTM_EXPORT(open);

#ifndef AT_FDCWD
#define AT_FDCWD (-100)
#endif

/**
 * @brief Opens a file relative to a directory file descriptor.
 *
 * @param dirfd The file descriptor of the directory to base the relative path on.
 * @param path The path to the file to be opened, relative to the directory specified by `dirfd`.
 *                 Can be an absolute path (in which case `dirfd` is ignored).
 * @param flag File access and status flags (e.g., `O_RDONLY`, `O_WRONLY`, `O_CREAT`).
 *
 * @return On success, returns a new file descriptor for the opened file.
 *         On failure, returns `-1` and sets `errno` to indicate the error.
 *
 * @note When using relative paths, ensure `dirfd` is a valid directory descriptor.
 *       When `pathname` is absolute, the `dirfd` argument is ignored.
 *
 */
int openat(int dirfd, const char *path, int flag, ...)
{
    struct dfs_file *d;
    char *fullpath;
    int fd;

    if (!path)
    {
        rt_set_errno(-EBADF);
        return -1;
    }

    fullpath = (char*)path;

    if (path[0] != '/')
    {
        if (dirfd != AT_FDCWD)
        {
            d = fd_get(dirfd);
            if (!d || !d->vnode)
            {
                rt_set_errno(-EBADF);
                return -1;
            }

            fullpath = dfs_dentry_full_path(d->dentry);
            if (!fullpath)
            {
                rt_set_errno(-ENOMEM);
                return -1;
            }
        }
    }

    fd = open(fullpath, flag, 0);

    if (fullpath != path)
    {
        rt_free(fullpath);
    }

    return fd;
}

int utimensat(int __fd, const char *__path, const struct timespec __times[2], int __flags)
{
    int ret;
    struct stat buffer;
    struct dfs_file *d;
    char *fullpath;
    struct dfs_attr attr;
    time_t current_time;
    char *link_fn = (char *)rt_malloc(DFS_PATH_MAX);
    int err;

    if (__path == NULL)
    {
        return -EFAULT;
    }

    if (__path[0] == '/' || __fd == AT_FDCWD)
    {
        if (stat(__path, &buffer) < 0)
        {
            return -ENOENT;
        }
        else
        {
            fullpath = (char*)__path;
        }
    }
    else
    {
        if (__fd != AT_FDCWD)
        {
            d = fd_get(__fd);
            if (!d || !d->vnode)
            {
                return -EBADF;
            }

            fullpath = dfs_dentry_full_path(d->dentry);
            if (!fullpath)
            {
                rt_set_errno(-ENOMEM);
                return -1;
            }
        }
    }

    /*update time*/
    attr.ia_valid = ATTR_ATIME_SET | ATTR_MTIME_SET;
    time(&current_time);
    if (UTIME_NOW == __times[0].tv_nsec)
    {
        attr.ia_atime.tv_sec = current_time;
    }
    else if (UTIME_OMIT != __times[0].tv_nsec)
    {
        attr.ia_atime.tv_sec = __times[0].tv_sec;
    }
    else
    {
        attr.ia_valid &= ~ATTR_ATIME_SET;
    }

    if (UTIME_NOW == __times[1].tv_nsec)
    {
        attr.ia_mtime.tv_sec = current_time;
    }
    else if (UTIME_OMIT == __times[1].tv_nsec)
    {
        attr.ia_mtime.tv_sec = __times[1].tv_sec;
    }
    else
    {
        attr.ia_valid &= ~ATTR_MTIME_SET;
    }

    if (dfs_file_lstat(fullpath, &buffer) == 0)
    {
        if (S_ISLNK(buffer.st_mode) && (__flags != AT_SYMLINK_NOFOLLOW))
        {
            if (link_fn)
            {
                err = dfs_file_readlink(fullpath, link_fn, DFS_PATH_MAX);
                if (err < 0)
                {
                    rt_free(link_fn);
                    return -ENOENT;
                }
                else
                {
                    fullpath = link_fn;
                    if (dfs_file_stat(fullpath, &buffer) != 0)
                    {
                        rt_free(link_fn);
                        return -ENOENT;
                    }
                }
            }

        }
    }
    attr.st_mode = buffer.st_mode;
    ret = dfs_file_setattr(fullpath, &attr);
    rt_free(link_fn);

    return ret;
}

/**
 * this function is a POSIX compliant version,
 * which will create a new file or rewrite an existing one
 *
 * @param path the path name of file.
 * @param mode the file permission bits to be used in creating the file (not used, can be 0)
 *
 * @return the non-negative integer on successful open, others for failed.
 */
int creat(const char *path, mode_t mode)
{
    return open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
}
RTM_EXPORT(creat);

/**
 * this function is a POSIX compliant version, which will close the open
 * file descriptor.
 *
 * @param fd the file descriptor.
 *
 * @return 0 on successful, -1 on failed.
 */
int close(int fd)
{
    int result;
    struct dfs_file *file;

    file = fd_get(fd);
    if (file == NULL)
    {
        rt_set_errno(-EBADF);

        return -1;
    }

    result = dfs_file_close(file);
    if (result < 0)
    {
        rt_set_errno(result);

        return -1;
    }

    fd_release(fd);

    return 0;
}
RTM_EXPORT(close);

/**
 * this function is a POSIX compliant version, which will read specified data
 * buffer length for an open file descriptor.
 *
 * @param fd the file descriptor.
 * @param buf the buffer to save the read data.
 * @param len the maximal length of data buffer
 *
 * @return the actual read data buffer length. If the returned value is 0, it
 * may be reach the end of file, please check errno.
 */
#if defined(RT_USING_NEWLIB) && defined(_EXFUN)
_READ_WRITE_RETURN_TYPE _EXFUN(read, (int fd, void *buf, size_t len))
#else
ssize_t read(int fd, void *buf, size_t len)
#endif
{
    ssize_t result;
    struct dfs_file *file;

    if (buf == NULL)
    {
        rt_set_errno(-EBADF);
        return -1;
    }

    file = fd_get(fd);
    if (file == NULL)
    {
        rt_set_errno(-EBADF);

        return -1;
    }

    result = dfs_file_read(file, buf, len);
    if (result < 0)
    {
        rt_set_errno(result);

        return -1;
    }

    return result;
}
RTM_EXPORT(read);

/**
 * this function is a POSIX compliant version, which will write specified data
 * buffer length for an open file descriptor.
 *
 * @param fd the file descriptor
 * @param buf the data buffer to be written.
 * @param len the data buffer length.
 *
 * @return the actual written data buffer length.
 */
#if defined(RT_USING_NEWLIB) && defined(_EXFUN)
_READ_WRITE_RETURN_TYPE _EXFUN(write, (int fd, const void *buf, size_t len))
#else
ssize_t write(int fd, const void *buf, size_t len)
#endif
{
    ssize_t result;
    struct dfs_file *file;

    if (buf == NULL)
    {
        rt_set_errno(-EBADF);
        return -1;
    }

    file = fd_get(fd);
    if (file == NULL)
    {
        rt_set_errno(-EBADF);

        return -1;
    }

    result = dfs_file_write(file, buf, len);
    if (result < 0)
    {
        rt_set_errno(result);

        return -1;
    }

    return result;
}
RTM_EXPORT(write);

/**
 * this function is a POSIX compliant version, which will Reposition the file offset for
 * an open file descriptor.
 *
 * The `lseek` function sets the file offset for the file descriptor `fd`
 * to a new value, determined by the `offset` and `whence` parameters.
 * It can be used to seek to specific positions in a file for reading or writing.
 *
 * @param fd the file descriptor.
 * @param offset The offset, in bytes, to set the file position.
 *               The meaning of `offset` depends on the value of `whence`.
 * @param whence the directive of seek. It can be one of:
 *               - `SEEK_SET`: Set the offset to `offset` bytes from the beginning of the file.
 *               - `SEEK_CUR`: Set the offset to its current location plus `offset` bytes.
 *               - `SEEK_END`: Set the offset to the size of the file plus `offset` bytes.
 *
 * @return the resulting read/write position in the file, or -1 on failed.
 */
off_t lseek(int fd, off_t offset, int whence)
{
    off_t result;
    struct dfs_file *file;

    file = fd_get(fd);
    if (file == NULL)
    {
        rt_set_errno(-EBADF);

        return -1;
    }

    result = dfs_file_lseek(file, offset, whence);
    if (result < 0)
    {
        rt_set_errno(-EPERM);

        return -1;
    }

    return result;
}
RTM_EXPORT(lseek);

/**
 * this function is a POSIX compliant version, which will rename old file name
 * to new file name.
 *
 * @param old_file the old file name.
 * @param new_file the new file name.
 *
 * @return 0 on successful, -1 on failed.
 *
 * note: the old and new file name must be belong to a same file system.
 */
int rename(const char *old_file, const char *new_file)
{
    int result;

    if (old_file == NULL || new_file == NULL)
    {
        rt_set_errno(-EBADF);
        return -1;
    }

    result = dfs_file_rename(old_file, new_file);
    if (result < 0)
    {
        rt_set_errno(result);

        return -1;
    }

    return 0;
}
RTM_EXPORT(rename);

/**
 * this function is a POSIX compliant version, which will unlink (remove) a
 * specified path file from file system.
 *
 * @param pathname the specified path name to be unlinked.
 *
 * @return 0 on successful, -1 on failed.
 */
int unlink(const char *pathname)
{
    int result;
    struct stat stat;

    if (pathname == NULL)
    {
        rt_set_errno(-EBADF);
        return -1;
    }

    result = dfs_file_lstat(pathname, &stat);
    if (result == 0 && S_ISDIR(stat.st_mode))
    {
        rt_set_errno(-RT_ERROR);

        return -1;
    }

    result = dfs_file_unlink(pathname);
    if (result < 0)
    {
        rt_set_errno(result);

        return -1;
    }

    return 0;
}
RTM_EXPORT(unlink);

