/**
 * this function is a POSIX compliant version, which shall check the file named
 * by the pathname pointed to by the path argument for accessibility according
 * to the bit pattern contained in amode.
 *
 * @param path the specified file/dir path.
 * @param amode the value is either the bitwise-inclusive OR of the access
 * permissions to be checked (R_OK, W_OK, X_OK) or the existence test (F_OK).
 */
int access(const char *path, int amode)
{
    struct stat st;

    if (path == NULL)
    {
        rt_set_errno(-EINVAL);
        return -1;
    }

    if (stat(path, &st) < 0)
    {
        rt_set_errno(-ENOENT);
        return -1;
    }

    if (amode == F_OK)
    {
        return 0;
    }

    if ((amode & R_OK) && !(st.st_mode & S_IRUSR))
    {
        rt_set_errno(-EACCES);
        return -1;
    }

    if ((amode & W_OK) && !(st.st_mode & S_IWUSR))
    {
        rt_set_errno(-EACCES);
        return -1;
    }

    if ((amode & X_OK) && !(st.st_mode & S_IXUSR))
    {
        rt_set_errno(-EACCES);
        return -1;
    }

    return 0;
}

/**
 * this function is a POSIX compliant version, which will set current
 * working directory.
 *
 * @param buf the current directory.
 */
void setcwd(char *buf)
{
    if (buf == NULL)
    {
        rt_set_errno(-EBADF);
        return;
    }

#ifdef DFS_USING_WORKDIR
    dfs_lock();
#ifdef RT_USING_SMART
    lwp_setcwd(buf);
#else
    rt_strncpy(working_directory, buf, DFS_PATH_MAX);
#endif
    dfs_unlock();
#else
    rt_kprintf(NO_WORKING_DIR);
#endif

    return ;
}
RTM_EXPORT(setcwd);

/**
 * this function is a POSIX compliant version, which will return current
 * working directory.
 *
 * @param buf the returned current directory.
 * @param size the buffer size.
 *
 * @return the returned current directory.
 */
char *getcwd(char *buf, size_t size)
{
    if (buf == NULL)
    {
        rt_set_errno(-EBADF);
        return NULL;
    }

#ifdef DFS_USING_WORKDIR
    char *dir_buf = RT_NULL;

    dfs_lock();

#ifdef RT_USING_SMART
    dir_buf = lwp_getcwd();
#else
    dir_buf = &working_directory[0];
#endif

    /* copy to buf parameter */
    if (buf)
    {
        rt_strncpy(buf, dir_buf, size);
        if (size > 0) buf[size - 1] = '\0';
    }

    dfs_unlock();
#else
    rt_kprintf(NO_WORKING_DIR);
#endif

    return buf;
}
RTM_EXPORT(getcwd);

/**
 * this function is a POSIX compliant version, which will read specified data
 * buffer length for an open file descriptor.
 *
 * @param fd the file descriptor.
 * @param buf the buffer to save the read data.
 * @param len the maximal length of data buffer
 * @param offset the file pos
 *
 * @return the actual read data buffer length. If the returned value is 0, it
 * may be reach the end of file, please check errno.
 */
ssize_t pread(int fd, void *buf, size_t len, off_t offset)
{
    ssize_t result;
    off_t fpos;
    struct dfs_file *file;

    if (buf == NULL)
    {
        rt_set_errno(-EBADF);
        return -1;
    }

    file = fd_get(fd);
    if (file == NULL)
    {
        rt_set_errno(-EBADF);

        return -1;
    }

    /* fpos lock */
    fpos = dfs_file_get_fpos(file);
    result = dfs_file_pread(file, buf, len, offset);
    /* fpos unlock */
    dfs_file_set_fpos(file, fpos);
    if (result < 0)
    {
        rt_set_errno(result);

        return -1;
    }

    return result;
}
RTM_EXPORT(pread);

/**
 * this function is a POSIX compliant version, which will write specified data
 * buffer length for an open file descriptor.
 *
 * @param fd the file descriptor
 * @param buf the data buffer to be written.
 * @param len the data buffer length.
 * @param offset the file pos
 *
 * @return the actual written data buffer length.
 */
ssize_t pwrite(int fd, const void *buf, size_t len, off_t offset)
{
    ssize_t result;
    off_t fpos;
    struct dfs_file *file;

    if (buf == NULL)
    {
        rt_set_errno(-EBADF);
        return -1;
    }

    file = fd_get(fd);
    if (file == NULL)
    {
        rt_set_errno(-EBADF);

        return -1;
    }
    /* fpos lock */
    fpos = dfs_file_get_fpos(file);
    result = dfs_file_pwrite(file, buf, len, offset);
    /* fpos unlock */
    dfs_file_set_fpos(file, fpos);
    if (result < 0)
    {
        rt_set_errno(result);

        return -1;
    }

    return result;
}
RTM_EXPORT(pwrite);

